 catalogLoadPending=(async()=>{
  do{
   catalogLoadQueued=false;const generation=catalogGeneration;
   try{
    const stages=!catalogLoaded&&api()?.CatalogIndexSnapshot?['CatalogIndexSnapshot','CatalogSnapshot']:['CatalogSnapshot'];
    for(const method of stages){
    const next=await call(method);
    if(generation!==catalogGeneration)break;
    if(!next||!Array.isArray(next.catalog)||!Array.isArray(next.sources)||next.catalog.some(g=>!g||typeof g!=='object'))throw Error('Le catalogue enregistré ne peut pas encore être chargé.');
    if(JSON.stringify(next.sources)!==JSON.stringify(data.sources)){reload({catalog:true}).catch(()=>{});break}
    data.catalog=hydrateCatalogRows(next.catalog);data.featured_key=next.featured_key||data.featured_key;data.catalog_updated=next.catalog_updated;catalogLoaded=true;catalogLoadError='';renderCatalogLoad();
    }
   }catch(e){if(generation===catalogGeneration){catalogLoadError=String(e?.message||e);renderCatalogLoad()}}
  }while(catalogLoadQueued)
 })();
