     if(JSON.stringify(data.sources)!==JSON.stringify(next.sources)){catalogGeneration++;catalogLoadQueued=!!catalogLoadPending;catalogLoaded=false;catalogDetailsCache.clear();data.catalog=[];catalogRefreshRequested=true}
     next.catalog=data.catalog||[];next.featured_key=data.featured_key;next.catalog_updated=data.catalog_updated;
