async function loadGameCompletion(g){if(preview||!api()?.CompleteGame||gameCompletionDone.has(g.uid)||gameCompletionPending.has(g.uid)||gameCompletionError.has(g.uid)||!gameNeedsCompletion(g))return;const uid=g.uid;gameCompletionPending.add(uid);gameCompletionFingerprints.set(uid,completionFingerprint(g));updateLibraryCompletionStatus();try{const completed=await call('CompleteGame',uid);completed.name=cleanGameTitle(completed.name);const item=data.games.find(v=>v.uid===uid);if(item){Object.assign(item,completed);gameCompletionFingerprints.set(uid,completionFingerprint(item));gameCompletionDone.add(uid)}gameCompletionError.delete(uid);gameImageRevision.set(uid,Date.now())}catch(e){gameCompletionError.set(uid,String(e?.message||e))}finally{gameCompletionPending.delete(uid);updateLibraryCompletionStatus();if((page==='detail'&&selected===uid)||['home','library','favorites'].includes(page))render()}}

const gameCompletionFingerprints=new Map();
function completionFingerprint(g){return JSON.stringify([g.name,g.steam_appid,g.igdb_id,g.cover_path,g.artwork_path,g.summary,g.metadata_version,g.steam_official_title,g.release_date,g.genres,g.developers,g.publishers,g.languages])}
function reconcileLibraryCompletion(){
 const games=new Map(list(data.games).map(g=>[g.uid,g]));
 for(const uid of new Set([...gameCompletionFingerprints.keys(),...gameCompletionDone,...gameCompletionError.keys()])){
  if(gameCompletionPending.has(uid))continue;
  const g=games.get(uid),signature=g?completionFingerprint(g):'';
  if(!g||gameCompletionFingerprints.get(uid)!==signature){gameCompletionDone.delete(uid);gameCompletionError.delete(uid);gameCompletionFingerprints.delete(uid)}
 }
 for(const g of games.values())if(!gameCompletionPending.has(g.uid))gameCompletionFingerprints.set(g.uid,completionFingerprint(g));
}
function resetIncompleteLibrarySearch(){for(const g of list(data.games))if(gameNeedsCompletion(g)&&!gameCompletionPending.has(g.uid)){gameCompletionDone.delete(g.uid);gameCompletionError.delete(g.uid)}}
function libraryCompletionStatus(){
 const games=list(data.games),pending=games.filter(g=>gameCompletionPending.has(g.uid)),failed=games.filter(g=>gameCompletionError.has(g.uid)),missing=games.filter(g=>!g.cover_path);
 if(pending.length)return `Recherche des images et informations : ${pending[0].name}…`;
 if(failed.length)return `Recherche interrompue pour ${failed.length} jeu(x) : ${gameCompletionError.get(failed[0].uid)}`;
 if(missing.length)return `${missing.length} jeu(x) sans jaquette pour le moment.`;
 return '';
}
function updateLibraryCompletionStatus(){const label=$('#library-completion-status');if(label){label.textContent=libraryCompletionStatus();label.hidden=!label.textContent}}
let libraryCompletionRunning=false;
async function scheduleLibraryCompletion(){
 if(preview||!api()?.CompleteGame||document.body.classList.contains('starting')||libraryCompletionRunning)return;
 reconcileLibraryCompletion();
 libraryCompletionRunning=true;
 try{
  while(true){
   const game=list(data.games).find(g=>g.uid&&!gameCompletionDone.has(g.uid)&&!gameCompletionPending.has(g.uid)&&!gameCompletionError.has(g.uid)&&gameNeedsCompletion(g));
   if(!game)break;
   await loadGameCompletion(game);
  }
 }finally{libraryCompletionRunning=false}
}
function updateProfileControls(){const nav=document.getElementById("cloud-nav");if(nav)nav.hidden=!data.cloud_connected||!!data.portable;const profile=document.querySelector(".profile-button");if(profile){profile.title=data.cloud_reconnect_required?"Reconnecter Google Drive":data.cloud_connected?"Profil Google · "+(data.cloud_email||"Compte connecté"):"Connecter Google Drive";profile.disabled=!!data.portable};if(typeof updateCloudStatus==='function')updateCloudStatus()}
function applyTheme(){document.querySelectorAll('[data-window="close"]').forEach(button=>{const title=data.preferences?.close_to_tray===false?'Quitter Ludemis':'Masquer Ludemis';button.title=title;button.setAttribute('aria-label',title)});updateProfileControls();const allowed=['graphite','ocean','copper','forest','atelier','orbit'];document.documentElement.dataset.theme=allowed.includes(data.theme)?data.theme:'graphite';document.documentElement.style.colorScheme=data.theme==='atelier'?'light':'dark';DesignStudio.apply(DesignStudio.isEditing()?DesignStudio.current():data.design,data.theme)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4000)}
async function task(fn,success){if(busy)return;busy=true;try{const r=await fn();if(success)toast(typeof success==='function'?success(r):success);await reload();return r}catch(e){toast(String(e?.message||e));throw e}finally{busy=false}}
function navigate(p,id){if(p==='design'){p='settings';SettingsOptions.openCategory('appearance')}if(DesignStudio.isEditing()&&p!==page){if(DesignStudio.dirty()&&!confirm('Quitter sans enregistrer ton design ?'))return;DesignStudio.cancel();applyTheme()}if(p==='catalog'&&page!=='catalog-detail')catalogPage=1;page=p;selected=id||selected;query='';filter='all';modal='';$('#modal-root').innerHTML='';render();view.scrollTo(0,0)}
function heading(kicker,title,sub='',actions=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${actions?`<div class="button-row">${actions}</div>`:''}</div>`}
function btn(label,action,style='',extra=''){return `<button class="btn ${style}" data-action="${action}" ${extra}>${esc(label)}</button>`}
function empty(icon,title,body,action='',label=''){return `<div class="empty"><div class="empty-icon">${icon}</div><h2>${esc(title)}</h2><p>${esc(body)}</p>${action?btn(label,action,'primary'):''}</div>`}
function coverArt(g,kind='cover'){return `<img src="${preview&&g.uid==='demo0'?'/demo-odyssey.jpg':img(g.uid,kind)}" alt="" loading="lazy" onerror="this.style.display='none'">`}
function card(g,landscape=false){let uid=esc(g.uid),name=esc(g.name),genre=esc(list(g.genres)[0]||'Jeu PC');if(landscape)return `<article class="landscape-card" data-open="${uid}" tabindex="0" aria-label="Voir ${name}"><div class="landscape-image">${coverArt(g,'artwork')}<span class="art-monogram">${esc(g.name.slice(0,2).toUpperCase())}</span><div class="landscape-overlay"><span class="mini-label">REPRENDRE</span><strong>${name}</strong>${steamIDBadge(g)}<small>${fmtTime(g.playtime_seconds)} de jeu <span>↗</span></small></div></div></article>`;
return `<article class="game-card" data-open="${uid}" tabindex="0" aria-label="Voir ${name}"><div class="cover"><div class="fallback"><span>${esc(g.name.slice(0,2).toUpperCase())}</span><strong>${name}</strong></div>${coverArt(g)}<span class="cover-sheen"></span><span class="card-open">↗</span></div><button class="card-heart ${g.favorite?'is-fav':''}" data-fav="${uid}" title="${g.favorite?'Retirer des favoris':'Ajouter aux favoris'}">${g.favorite?'♥':'♡'}</button><div class="card-body"><h3>${name}</h3>${steamIDBadge(g)}<p>${genre}<span>·</span>${fmtTime(g.playtime_seconds)}</p></div></article>`}
function catalogRemoteImage(raw){const value=String(raw||'');try{const u=new URL(value);return u.protocol==='https:'&&(/(^|\.)igdb\.com$|(^|\.)steamstatic\.com$/).test(u.hostname)?value:''}catch{return ''}}
const catalogRepairAttempts=new Map();
function repairCatalogImage(key){if(preview||!api()?.RepairCatalogImages||catalogRepairAttempts.has(key))return;catalogRepairAttempts.set(key,Date.now());call('RepairCatalogImages',key).catch(()=>{})}
const catalogCoverFailures=new Map();
function catalogCoverAttempt(g){return JSON.stringify([catalogMedia(catalogKey(g),g.image_kind==='hero'?'hero':''),catalogRemoteImage(g.cover_url)])}
function catalogCoverMissing(g){return catalogCoverFailures.get(catalogKey(g))===catalogCoverAttempt(g)}
function catalogCoverImage(g){const key=catalogKey(g),missing=catalogCoverMissing(g);return `<img ${missing?'':'src="'+catalogMedia(key,g.image_kind==='hero'?'hero':'')+'"'} data-attempt="${esc(catalogCoverAttempt(g))}" data-remote="${esc(catalogRemoteImage(g.cover_url))}" alt="" loading="lazy" style="${missing?'display:none':'visibility:hidden'}" onload="catalogCoverLoaded(this)" onerror="catalogCoverFailed(this)">`}
function catalogCoverLoaded(image){const card=image.closest('.catalog-card');image.style.visibility='visible';image.style.display='';card?.classList.remove('missing-cover');card?.classList.add('has-cover');if(card)catalogCoverFailures.delete(card.dataset.catalog);updateCatalogPageStatus()}
function catalogCoverFailed(image){if(image.dataset.remote&&!image.dataset.used){image.dataset.used='1';image.src=image.dataset.remote;return}image.style.display='none';const card=image.closest('.catalog-card');card?.classList.remove('has-cover');card?.classList.add('missing-cover');if(card){catalogCoverFailures.set(card.dataset.catalog,image.dataset.attempt);repairCatalogImage(card.dataset.catalog);hideCatalogGame(card.dataset.catalog)}updateCatalogPageStatus()}
function catalogCard(g){const key=catalogKey(g),title=cleanGameTitle(g.title);return `<article class="game-card catalog-card${catalogCoverMissing(g)?' missing-cover':''}" data-catalog="${esc(key)}" tabindex="0"><div class="cover">${catalogCoverImage(g)}${ratingBadge(g)}<span class="cover-sheen"></span><span class="card-open">↗</span></div><div class="card-body"><h3 title="${esc(title)}">${esc(title)}</h3>${steamIDBadge(g)}</div></article>`}
const reviewCache=new Map(),reviewPending=new Set(),reviewErrors=new Map();let reviewLanguage='french';
const trailerCache=new Map(),trailerPending=new Set(),trailerErrors=new Set();
function trailerKey(g){return (g.uid?'library:':'catalog:')+(g.uid||catalogKey(g))}
function trailerPanel(g){const key=trailerKey(g),videos=trailerCache.get(key),error=trailerErrors.has(key);return `<section class="panel trailer-panel" data-trailer="${esc(key)}"><div class="section-head"><h2>Bande-annonce</h2><span class="eyebrow">YOUTUBE</span></div>${videos?.length?`<div class="trailer-carousel"><button type="button" class="trailer-arrow" data-trailer-direction="-1" aria-label="Vidéo précédente" ${videos.length<2?'disabled':''}>‹</button><div class="trailer-center"><div class="trailer-timer" data-trailer-timer hidden aria-live="polite"><span data-trailer-countdown></span><div class="trailer-timer-track"><i data-trailer-progress></i></div></div><div class="trailer-player"><iframe src="https://www.youtube-nocookie.com/embed/${videos[0].id}?enablejsapi=1&autoplay=0&rel=0&playsinline=1&hl=fr" title="${esc(videos[0].name)}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; fullscreen" allowfullscreen></iframe></div><div class="trailer-caption"><span data-trailer-title>${esc(videos[0].name)}</span><small data-trailer-count>1 / ${videos.length}</small></div></div><button type="button" class="trailer-arrow" data-trailer-direction="1" aria-label="Vidéo suivante" ${videos.length<2?'disabled':''}>›</button></div><button class="text-link" data-action="open-trailer" data-video="${videos[0].id}">Ouvrir sur YouTube ↗</button>`:`<p class="achievement-note">${error?'Bandes-annonces momentanément indisponibles.':videos?'Aucune bande-annonce référencée pour ce jeu.':'Recherche de la bande-annonce…'}</p>`}</section>`}
function mountTrailerCarousel(){if(typeof TrailerCarousel==='undefined')return;const panel=view.querySelector('[data-trailer]');TrailerCarousel.mount(panel?.querySelector('iframe')?panel:null,panel?trailerCache.get(panel.dataset.trailer):null)}

async function loadTrailers(g){const key=trailerKey(g);if(preview||!api()?.GameTrailers||trailerCache.has(key)||trailerPending.has(key)||trailerErrors.has(key))return;trailerPending.add(key);try{const videos=await call('GameTrailers',g.uid||catalogKey(g),!g.uid);trailerCache.set(key,list(videos).filter(v=>/^[a-zA-Z0-9_-]{11}$/.test(v.id)))}catch{trailerErrors.add(key)}finally{trailerPending.delete(key);const panel=view.querySelector('[data-trailer]');if(panel?.dataset.trailer===key)panel.outerHTML=trailerPanel(g);mountTrailerCarousel()}}
const timeToBeatCache=new Map(),timeToBeatPending=new Set(),timeToBeatErrors=new Set();
function timeToBeatKey(g){return (g.uid?'library:':'catalog:')+(g.uid||catalogKey(g))}
function formatBeatTime(seconds){const value=Number(seconds);if(!Number.isFinite(value)||value<=0)return 'Non renseigné';const minutes=Math.max(1,Math.round(value/60)),hours=Math.floor(minutes/60),rest=minutes%60;return hours?hours+' h'+(rest?' '+rest+' min':''):minutes+' min'}
function timeToBeatPanel(g){const key=timeToBeatKey(g),times=timeToBeatCache.get(key),failed=timeToBeatErrors.has(key);return `<section class="panel time-to-beat-panel" data-time-to-beat="${esc(key)}"><div class="time-to-beat-heading"><h2>Durée du jeu</h2><small>Estimations IGDB</small></div><div class="time-to-beat-grid">${[['hastily','Rapide','Histoire principale'],['normally','Normale','Histoire et quelques extras'],['completely','Complète','Objectif 100 %']].map(([field,label,description])=>`<div><span>${label}</span><strong>${times?esc(formatBeatTime(times[field])):failed?'—':'…'}</strong><small>${description}</small></div>`).join('')}</div><p>${failed?'Durées momentanément indisponibles.':times?'Moyennes des joueurs'+(Number(times.count)>0?' · '+Number(times.count).toLocaleString('fr-FR')+' contributions':'')+'.':'Recherche des durées…'}</p></section>`}
async function loadTimeToBeat(g){const key=timeToBeatKey(g);if(preview||!api()?.GameTimeToBeat||timeToBeatCache.has(key)||timeToBeatPending.has(key)||timeToBeatErrors.has(key))return;timeToBeatPending.add(key);try{timeToBeatCache.set(key,await call('GameTimeToBeat',g.uid||catalogKey(g),!g.uid))}catch{timeToBeatErrors.add(key)}finally{timeToBeatPending.delete(key);const panel=view.querySelector('[data-time-to-beat]');if(panel?.dataset.timeToBeat===key)panel.outerHTML=timeToBeatPanel(g)}}
function steamID(g){const id=String(g?.steam_appid??g?.steam_app_id??'').replace(/\.0$/,'');return /^\d{1,12}$/.test(id)&&Number(id)>0?id:''}
const steamRatingCache=new Map(),steamRatingPending=new Set(),steamRatingErrors=new Set();
let activeSteamRatingLoads=0;const steamRatingWaiters=[];
async function acquireSteamRatingSlot(){if(activeSteamRatingLoads<3){activeSteamRatingLoads++;return}await new Promise(resolve=>steamRatingWaiters.push(resolve))}
function releaseSteamRatingSlot(){const next=steamRatingWaiters.shift();if(next)next();else activeSteamRatingLoads--}
function ratingGameKey(g){return g.uid?'library:'+g.uid:'catalog:'+catalogKey(g)}
function ratingFact(g){const score=GameRatings.score(g);return `<div data-rating-game="${esc(ratingGameKey(g))}" data-rating-kind="fact"><small>NOTE ${score?.source||''}</small><strong title="${score?.source==='Steam'?'Taux d’avis positifs · '+score.total.toLocaleString('fr-FR')+' avis · toutes langues':'Note IGDB convertie sur 10'}">${esc(GameRatings.text(score))}</strong></div>`}
function ratingBadge(g){const score=GameRatings.score(g);return `<span class="cover-rating" data-rating-game="${esc(ratingGameKey(g))}" data-rating-kind="badge" ${score?'':'hidden'} title="${score?.source==='Steam'?'Taux d’avis positifs Steam · '+score.total.toLocaleString('fr-FR')+' avis':'IGDB'}" aria-label="Note ${score?.source||''} ${esc(GameRatings.text(score))}">${score?`★ ${esc(GameRatings.text(score))}<small>${score.source}</small>`:''}</span>`}
function updateRatingWidgets(g){for(const node of view.querySelectorAll('[data-rating-game]'))if(node.dataset.ratingGame===ratingGameKey(g))node.outerHTML=node.dataset.ratingKind==='badge'?ratingBadge(g):ratingFact(g)}
async function loadSteamRating(g){const id=steamID(g);if(!id||GameRatings.score(g)?.source==='IGDB'||steamRatingPending.has(id)||steamRatingErrors.has(id)||preview||!api()?.SteamRating)return;const apply=result=>{for(const item of [g,...(data.catalog||[]),...(data.games||[])])if(steamID(item)===id){item.steam_positive=result.positive;item.steam_negative=result.negative;updateRatingWidgets(item)}};if(steamRatingCache.has(id)){apply(steamRatingCache.get(id));return}steamRatingPending.add(id);await acquireSteamRatingSlot();try{const result=await call('SteamRating',id);steamRatingCache.set(id,result);apply(result)}catch{steamRatingErrors.add(id)}finally{steamRatingPending.delete(id);releaseSteamRatingSlot()}}
function steamIDBadge(g){const id=steamID(g);return `<p class="steam-id${id?'':' is-unknown'}" aria-label="Steam App ID : ${id||'non identifié'}">Steam App ID : <span>${id||'non identifié'}</span></p>`}
function currentReviewGame(){return page==='detail'?data.games.find(g=>g.uid===selected):page==='catalog-detail'?data.catalog.find(g=>catalogKey(g)===catalogSelected):null}
function reviewKey(g){return steamID(g)+':'+reviewLanguage}
function steamSummary(v){return ({'Overwhelmingly Positive':'Extrêmement positives','Very Positive':'Très positives','Mostly Positive':'Plutôt positives','Positive':'Positives','Mixed':'Partagées','Negative':'Négatives','Mostly Negative':'Plutôt négatives','Very Negative':'Très négatives','Overwhelmingly Negative':'Extrêmement négatives'})[v]||v||'Avis de la communauté'}
function reviewDate(ts){return ts?new Date(Number(ts)*1000).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}):''}
function reviewCard(r){return `<article class="review-card ${r.positive?'positive':'negative'}"><div class="review-top"><span class="review-avatar">S</span><div><strong>Joueur Steam</strong><small>${esc(reviewDate(r.created_at))}${r.playtime_minutes?` · ${fmtTime(r.playtime_minutes*60)} sur Steam`:''}</small></div><span class="review-vote">${r.positive?'✓ Recommandé':'✕ Non recommandé'}</span></div><p>${esc(r.text||r.review||'')}</p><div class="review-bottom"><span>${r.helpful?`${Number(r.helpful).toLocaleString('fr-FR')} avis utiles`:'Avis de la communauté'}</span><span>STEAM</span></div></article>`}
function languagesPanel(g){const langs=list(g.languages);return `<section class="panel language-panel"><div class="panel-heading"><div><div class="eyebrow">ACCESSIBILITÉ LINGUISTIQUE</div><h2>Langues disponibles</h2></div><span class="panel-count">${langs.length} langue${langs.length>1?'s':''}</span></div>${langs.length?`<div class="language-table"><div class="language-row language-header"><span>LANGUE</span><span>INTERFACE</span><span>AUDIO</span><span>SOUS-TITRES</span></div>${langs.map(l=>`<div class="language-row"><strong>${esc(l.name)}</strong><span class="${l.interface?'yes':'no'}" aria-label="Interface ${l.interface?'disponible':'non indiquée'}">${l.interface?'✓':'—'}</span><span class="${l.audio?'yes':'no'}" aria-label="Audio ${l.audio?'disponible':'non indiqué'}">${l.audio?'✓':'—'}</span><span class="${l.subtitles?'yes':'no'}" aria-label="Sous-titres ${l.subtitles?'disponibles':'non indiqués'}">${l.subtitles?'✓':'—'}</span></div>`).join('')}</div>`:'<p class="metadata-empty">Aucune langue renseignée dans les métadonnées de ce jeu.</p>'}</section>`}
function metadataPanel(g){const groups=[['GENRES',g.genres],['MODES DE JEU',g.game_modes],['PERSPECTIVES',g.perspectives],['THÈMES',g.themes],['FRANCHISES',g.franchises]];return `<section class="panel metadata-panel"><div class="eyebrow">DONNÉES DU JEU</div><h2>Univers & caractéristiques</h2><div class="metadata-groups">${groups.map(([label,items])=>`<div><small>${label}</small><div class="tag-list">${list(items).length?list(items).map(v=>`<span class="tag">${esc(v)}</span>`).join(''):'<span class="metadata-dash">Non renseigné</span>'}</div></div>`).join('')}</div>${g.pegi_synopsis?`<div class="pegi-note"><strong>Classification</strong><p>${esc(g.pegi_synopsis)}</p></div>`:''}</section>`}
function cachedReviews(g){return list(g.steam_reviews).map(r=>({text:r.review,positive:r.positive,created_at:r.created_at,playtime_minutes:r.playtime_minutes}))}
function steamReviewsPanel(g){const id=steamID(g),key=reviewKey(g),result=reviewCache.get(key),error=reviewErrors.get(key),stored=cachedReviews(g),fallback=!result&&!!error&&stored.length;const reviews=result?.reviews|| (fallback?stored:[]);const total=result?.total_reviews??(fallback?Number(g.steam_review_total)||0:0),positive=result?.positive||0,negative=result?.negative||0,steamNote=GameRatings.steamScore(positive,negative);return `<section class="panel steam-panel" data-steam-panel="${esc(key)}"><div class="panel-heading"><div><div class="eyebrow">LA COMMUNAUTÉ / STEAM</div><h2>Avis des joueurs</h2></div><div class="review-filters"><button data-review-language="french" class="${reviewLanguage==='french'?'selected':''}" aria-pressed="${reviewLanguage==='french'}">Français</button><button data-review-language="all" class="${reviewLanguage==='all'?'selected':''}" aria-pressed="${reviewLanguage==='all'}">Toutes langues</button></div></div>${!id?`<div class="review-status">Aucun identifiant Steam associé à ce jeu. Les avis directs ne sont pas disponibles.${g.uid?`<div class="top-gap">${btn('Renseigner l’AppID Steam','edit','',`data-uid="${esc(g.uid)}"`)}</div>`:''}</div>`:`<div class="review-summary"><div class="review-score"><span class="review-score-icon">${result||fallback?'★':'○'}</span><div><strong>${esc(result?steamSummary(result.summary):fallback?steamSummary(g.steam_review_summary):'Avis Steam')}</strong><small>${total?`${Number(total).toLocaleString('fr-FR')} avis ${reviewLanguage==='french'?'en français':'au total'}`:'Avis récents de la communauté'}</small></div></div>${steamNote?`<div class="review-percent"><b>${esc(GameRatings.text(steamNote))}</b><small>AVIS POSITIFS</small></div>`:''}</div>${preview?'<p class="review-notice">Exemple visuel : ces avis sont fictifs. Le logiciel charge les vrais avis directement depuis Steam.</p>':fallback?'<p class="review-notice">Steam est momentanément indisponible. Avis enregistrés précédemment affichés.</p>':error?`<p class="review-notice error">${esc(error)} <button data-action="retry-reviews" class="text-link">Réessayer</button></p>`:''}${reviews.length?`<div class="review-grid">${reviews.map(reviewCard).join('')}</div>`:!result&&!error&&!preview?'<div class="review-status">Chargement des avis Steam…</div>':'<div class="review-status">Aucun avis disponible pour ce filtre.</div>'}`}</section>`}
async function loadSteamReviews(g){const id=steamID(g);if(!id)return;const key=reviewKey(g);if(reviewCache.has(key)||reviewPending.has(key))return;reviewPending.add(key);try{let result;if(preview){result={summary:'Very Positive',total_reviews:246,positive:223,negative:23,reviews:[{text:'Un exemple de présentation pour juger la lisibilité des avis. Dans le logiciel, ce texte sera remplacé par un véritable avis Steam.',positive:true,created_at:1720000000,playtime_minutes:420,helpful:12},{text:'Deuxième avis fictif pour montrer l’apparence d’une recommandation négative.',positive:false,created_at:1710000000,playtime_minutes:95,helpful:3}]}}else result=await call('SteamReviews',id,reviewLanguage);reviewCache.set(key,result);reviewErrors.delete(key)}catch(e){reviewErrors.set(key,String(e?.message||e))}finally{reviewPending.delete(key);const current=currentReviewGame(),panel=$('[data-steam-panel]');if(current&&reviewKey(current)===key&&panel?.dataset.steamPanel===key){panel.outerHTML=steamReviewsPanel(current);requestAnimationFrame(updatePageScrollbar)}}}
function stats(){let games=data.games||[];return [{v:games.length,l:'JEUX DANS LA COLLECTION'},{v:games.filter(g=>g.favorite).length,l:'FAVORIS'},{v:fmtTime(games.reduce((n,g)=>n+(g.playtime_seconds||0),0)),l:'TEMPS DE JEU'},{v:games.filter(g=>g.last_played).length,l:'JEUX LANCÉS'}]}
function statsHTML(){return `<div class="stat-strip">${stats().map(s=>`<div class="stat"><b>${esc(s.v)}</b><small>${esc(s.l)}</small></div>`).join('')}</div>`}
function homeFeaturedGame(snapshot){
 const rows=visibleCatalog(snapshot.catalog).filter(g=>g&&String(g.title||'').trim()&&catalogKey(g));
 const preferred=rows.find(g=>catalogKey(g)===snapshot.featured_key);if(preferred)return preferred;
 const reviews=g=>Math.max(0,Number(g.steam_review_total)||0,(Number(g.steam_positive)||0)+(Number(g.steam_negative)||0));
 return rows.reduce((best,g)=>!best||reviews(g)>reviews(best)||(reviews(g)===reviews(best)&&(Number(g.rating)||0)>(Number(best.rating)||0))?g:best,null);
}
function homeCatalogSuggestions(snapshot,limit=3,day=new Date().toISOString().slice(0,10)){
 const title=g=>cleanGameTitle(g.title||g.name||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
 const id=g=>String(g.steam_appid||g.steam_app_id||'').replace(/\.0$/,'');
 const installed=snapshot.games||[],ids=new Set(installed.map(id).filter(Boolean)),titles=new Set(installed.map(title).filter(Boolean));
 const featured=homeFeaturedGame(snapshot),featuredKey=featured?catalogKey(featured):'';
 if(featured){if(id(featured))ids.add(id(featured));titles.add(title(featured))}
 const score=g=>{let hash=2166136261;for(const c of day+catalogKey(g))hash=Math.imul(hash^c.charCodeAt(0),16777619);return hash>>>0};
 const rows=[...visibleCatalog(snapshot.catalog)].filter(g=>g&&String(g.title||'').trim()).sort((a,b)=>score(a)-score(b)||catalogKey(a).localeCompare(catalogKey(b)));
 const selected=[];
 for(const g of rows){const key=catalogKey(g),name=title(g),steam=id(g);if(key===featuredKey||titles.has(name)||(steam&&ids.has(steam)))continue;selected.push(g);titles.add(name);if(steam)ids.add(steam);if(selected.length>=limit)break}
 return selected;
}
function homeCatalogSuggestionCard(g){const key=catalogKey(g),name=cleanGameTitle(g.title);return `<article class="landscape-card home-catalog-suggestion" data-catalog="${esc(key)}" tabindex="0" aria-label="Voir ${esc(name)}"><div class="landscape-image"><img src="${catalogMedia(key,'hero')}" alt="" data-home-art="${esc(key)}" onerror="homeHeroImageFailed(this)"><span class="art-monogram">${esc(name.slice(0,2).toUpperCase())}</span><div class="landscape-overlay"><span class="mini-label">À DÉCOUVRIR</span><strong>${esc(name)}</strong><small>Voir la fiche du catalogue <span>↗</span></small></div></div></article>`}
function visibleCatalog(rows=data.catalog){return (rows||[]).filter(g=>g?.image_ready===true&&(typeof catalogCoverMissing!=='function'||!catalogCoverMissing(g)))}
let catalogVisibilityTimer=null;
function scheduleCatalogVisibilityRender(){if(catalogVisibilityTimer!==null)return;catalogVisibilityTimer=setTimeout(()=>{catalogVisibilityTimer=null;renderCatalogLoad();if(modal==='search')updateSearch()},150)}
function hideCatalogGame(key){const game=data.catalog.find(g=>catalogKey(g)===key);if(game)game.image_ready=false;scheduleCatalogVisibilityRender()}
async function refreshCatalogVisibility(key){
 if(!data.catalog.some(g=>catalogKey(g)===key)||!api()?.CatalogImageState)return;
 try{const full=await call('CatalogImageState',key),game=data.catalog.find(g=>catalogKey(g)===key);if(!game)return;applyPreparedCatalogGame(full);game.image_ready=full.image_ready===true;game.image_kind=full.image_kind||'';catalogImageRevision.set(key,Date.now());if(game.image_ready)catalogCoverFailures.delete(key);scheduleCatalogVisibilityRender()}catch{}
}
function homeHeroImageFailed(image){
 const key=image.dataset.homeArt,g=data.catalog.find(g=>catalogKey(g)===key);if(!g){image.style.display='none';return}
 const id=String(g.steam_app_id||g.steam_appid||'');
 const candidates=[catalogMedia(key),catalogRemoteImage(g.artwork_url),catalogRemoteImage(g.cover_url),/^\d+$/.test(id)?`https://cdn.cloudflare.steamstatic.com/steam/apps/${id}/header.jpg`:''].filter(Boolean);
 const attempt=Number(image.dataset.fallback||0);image.dataset.fallback=attempt+1;
 if(attempt<candidates.length){image.classList.toggle('is-cover',attempt===0||attempt===2);image.src=candidates[attempt]}else{image.style.display='none';hideCatalogGame(key)};
}
function home(){const games=data.games||[],suggestions=homeCatalogSuggestions(data),feature=homeFeaturedGame(data),key=feature?catalogKey(feature):'',name=feature?.title||'Découvre ton prochain jeu';let logo=official13Logo(feature)||catalogMedia(key,'logo');let stageArt=feature?catalogMedia(key,'hero'):'',artFallback=feature?catalogMedia(key):'';let hero=`<section class="stage-hero cinematic-hero">${feature?`<img class="stage-art" src="${stageArt}" alt="" data-home-art="${esc(key)}" onerror="homeHeroImageFailed(this)"><img class="stage-poster" src="${artFallback}" alt="" onerror="this.style.display='none'">`:''}<div class="stage-grain"></div><div class="stage-content">${feature?'':'<div class="stage-kicker"><span class="pulse-dot"></span>TON UNIVERS COMMENCE ICI</div>'}<h1>${feature?`<img class="home-title-logo" src="${logo}" data-official-fallback="${official13Logo(feature)?catalogMedia(key,'logo'): ''}" alt="${esc(name)}" onload="this.nextElementSibling.hidden=true" onerror="if(this.dataset.officialFallback&&!this.dataset.triedOfficial){this.dataset.triedOfficial='1';this.src=this.dataset.officialFallback}else this.remove()">`:''}<span class="home-title-text">${esc(name)}</span></h1><p>${esc(short(feature?.summary||'Découvre un jeu.',165))}</p><div class="stage-actions">${feature?btn('Voir la fiche  ↗','', 'primary large',`data-catalog="${esc(key)}"`)+btn('+  Ajouter à ma bibliothèque','catalog-add','ghost large',`data-key="${esc(key)}"`):`<button class="btn primary large" data-page="catalog">Parcourir le catalogue</button>`}</div></div></section>`;
return `<div class="home-feature">${hero}</div><div class="home-dashboard"><div class="dash-label"><span class="eyebrow">TA COLLECTION</span><strong>En un regard</strong></div><div class="dash-metric"><b>${String(games.length).padStart(2,'0')}</b><small>JEUX</small></div><div class="dash-metric"><b>${String(games.filter(g=>g.favorite).length).padStart(2,'0')}</b><small>FAVORIS</small></div><div class="dash-metric"><b>${Math.floor(games.reduce((n,g)=>n+(g.playtime_seconds||0),0)/3600)} h</b><small>DE JEU</small></div><button class="dash-link" data-page="library">OUVRIR LA BIBLIOTHÈQUE <span>↗</span></button></div><div class="section-head editorial"><div><div class="eyebrow">LE CATALOGUE</div><h2>À découvrir<span class="heading-dot">.</span></h2></div><button class="text-link" data-page="catalog">VOIR LE CATALOGUE <span>↗</span></button></div>${suggestions.length?`<div class="rail">${suggestions.map(homeCatalogSuggestionCard).join('')}</div>`:empty('↗','Le catalogue t’attend',catalogLoaded?'Tous les jeux disponibles sont déjà dans ta sélection.':'Les suggestions apparaîtront après le chargement du catalogue.','catalog','Ouvrir le catalogue')}<div class="section-head editorial"><div><div class="eyebrow">TA SÉLECTION</div><h2>La collection<span class="heading-dot">.</span></h2></div><button class="text-link" data-page="library">PARCOURIR <span>↗</span></button></div><p id="library-completion-status" class="profile-note" role="status" ${libraryCompletionStatus()?'':'hidden'}>${esc(libraryCompletionStatus())}</p>${games.length?`<div class="game-grid">${games.slice(0,8).map(g=>card(g)).join('')}</div>`:empty('＋','Une page blanche à remplir','Ajoute un jeu pour commencer ta collection.','add','Ajouter un jeu')}`}

function library(favorites=false){let games=[...(data.games||[])];if(favorites)games=games.filter(g=>g.favorite);if(filter==='played')games=games.filter(g=>g.last_played);if(filter==='unplayed')games=games.filter(g=>!g.last_played);if(query)games=games.filter(g=>matchesSearch(g.name+' '+list(g.genres).join(' '),query));games.sort((a,b)=>sort==='recent'?(b.last_played||0)-(a.last_played||0):sort==='time'?(b.playtime_seconds||0)-(a.playtime_seconds||0):a.name.localeCompare(b.name,'fr'));
return `<div class="collection-head"><div class="eyebrow">COLLECTION / ${favorites?'FAVORIS':'BIBLIOTHÈQUE'}</div><h1>${favorites?'Mes favoris':'Ma bibliothèque'}<span class="heading-dot">.</span></h1><div class="collection-sub"><p>${games.length} jeu${games.length>1?'x':''} à portée de main</p><div class="button-row">${btn('⌕  Scanner','scan')}${btn('+  Ajouter un jeu','add','primary')}</div></div></div><div class="toolbar collection-toolbar"><div class="tabs">${['all','played','unplayed'].map(v=>`<button data-filter="${v}" class="${filter===v?'selected':''}">${{all:'Tous',played:'Déjà joués',unplayed:'Jamais lancés'}[v]}</button>`).join('')}</div><div class="button-row"><input class="input search-field" id="library-search" placeholder="Rechercher un jeu…" value="${esc(query)}"><select class="input" id="library-sort"><option value="name" ${sort==='name'?'selected':''}>Nom A → Z</option><option value="recent" ${sort==='recent'?'selected':''}>Récemment joués</option><option value="time" ${sort==='time'?'selected':''}>Temps de jeu</option></select></div></div>${games.length?`<div class="game-grid">${games.map(g=>card(g)).join('')}</div>`:empty('♡',favorites?'Aucun favori pour l’instant':'Aucun jeu trouvé',favorites?'Marque un jeu avec le cœur pour le retrouver ici.':'Ajoute un jeu ou adapte les filtres.',favorites?'':'add','Ajouter un jeu')}`}
function facts(items){return `<div class="facts">${items.map(([k,v])=>`<div class="fact"><small>${esc(k)}</small><strong>${esc(v||'—')}</strong></div>`).join('')}</div>`}
function updateDetailTransition(image){const band=view.querySelector('.detail-image-transition');if(!band||!image?.naturalWidth||image.style.display==='none')return;try{const canvas=document.createElement('canvas');canvas.width=24;canvas.height=8;const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,image.naturalHeight*.7,image.naturalWidth,image.naturalHeight*.3,0,0,24,8);const pixels=context.getImageData(0,0,24,8).data;for(let section=0;section<3;section++){const totals=[0,0,0];let count=0;for(let y=0;y<8;y++)for(let x=section*8;x<(section+1)*8;x++){const i=(y*24+x)*4;if(pixels[i+3]<128)continue;for(let c=0;c<3;c++)totals[c]+=pixels[i+c];count++}if(count)view.style.setProperty(`--transition-${section}`,totals.map(v=>Math.round(v/count)).join(' '))}}catch{band.style.backgroundImage=`url(${JSON.stringify(image.currentSrc||image.src)})`;band.classList.add('uses-image')}}
function detailAtmosphere(src,cover,remote=''){return `<div class="detail-scroll-backdrop" aria-hidden="true"><img src="${src}" data-cover="${cover}" data-remote="${esc(remote)}" alt="" onerror="if(this.dataset.remote&&!this.dataset.remoteUsed){this.dataset.remoteUsed='1';this.src=this.dataset.remote}else if(!this.dataset.coverUsed){this.dataset.coverUsed='1';this.classList.add('is-cover');this.src=this.dataset.cover}else this.style.display='none'"></div>`}
const achievementCache=new Map(),achievementErrors=new Map(),achievementPending=new Set(),achievementProgressPending=new Set();
function achievementKey(g){return `${g.uid}:${steamID(g)||'unknown'}`}
function achievementCards(result,items){return items.map(a=>`<article class="achievement-card ${a.unlocked===true?'is-unlocked':'is-locked'}"><div class="achievement-icon"><img loading="lazy" src="/media/achievements/${encodeURIComponent(result.appid)}/${encodeURIComponent(a.id)}" alt="" onerror="this.hidden=true;this.parentElement.classList.add('missing-icon')"><span aria-hidden="true">★</span></div><div class="achievement-copy"><h3>${esc(a.name)}</h3><span class="achievement-state">${a.unlocked===true?'✓ Déverrouillé':a.known?'Verrouillé':'Progression inconnue'}</span><p>${esc(a.description||'Description non publiée par Steam.')}</p>${typeof a.global_percent==='number'?`<small>${a.global_percent.toLocaleString('fr-FR',{maximumFractionDigits:1})} % des joueurs Steam</small>`:''}</div></article>`).join('')}
function unlockedFirst(items){return [...items].sort((a,b)=>Number(b.unlocked===true)-Number(a.unlocked===true))}
function achievementsPanel(g){const key=achievementKey(g),result=achievementCache.get(key),error=achievementErrors.get(key),none=result?.items?.length===0;return `<section class="panel achievements-panel" tabindex="-1" data-achievements="${esc(key)}"><div class="achievements-header"><div><span class="eyebrow">OBJECTIFS & DÉFIS</span><h2>Succès${result&&!none?` <span class="achievement-count">${result.items.length}</span>`:''}</h2></div><div class="button-row">${result&&!none?btn('Tester la notification','achievement-notifications')+btn('⚙ Options','achievement-options','',`data-uid="${esc(g.uid)}"`)+btn('Actualiser','refresh-achievements','',`data-uid="${esc(g.uid)}"`)+btn('Voir tous les succès','show-achievements','',`data-uid="${esc(g.uid)}"`):''}</div></div>${none?'<p class="achievement-empty" role="status">Aucun succès pour ce jeu.</p>':result?`<div class="achievement-grid">${achievementCards(result,unlockedFirst(result.items).slice(0,4))}</div><p class="achievement-note">${esc(result.progress_message||'Recherche de la progression Achievement Watcher…')}${result.stale?' Liste enregistrée : Steam est temporairement indisponible.':''}</p>`:error?`<div class="achievement-empty"><p>${esc(error)}</p>${btn('Réessayer','retry-achievements','',`data-uid="${esc(g.uid)}"`)}</div>`:`<p class="achievement-empty" role="status">${steamID(g)?'Chargement des succès Steam…':'Les succès seront recherchés après l’identification Steam du jeu.'}</p>`}</section>`}
async function loadAchievements(g){if(!g.uid||!steamID(g)||preview)return;const key=achievementKey(g);if(achievementCache.has(key)||achievementPending.has(key)||achievementErrors.has(key))return;achievementPending.add(key);try{const result=await call('GameAchievements',g.uid);if(!result||!Array.isArray(result.items))throw new Error('La liste des succès est indisponible.');achievementCache.set(key,result);await refreshAchievementProgress(g)}catch(e){achievementErrors.set(key,String(e?.message||e))}finally{achievementPending.delete(key);const panel=view.querySelector('[data-achievements]');if(page==='detail'&&selected===g.uid&&panel?.dataset.achievements===key){panel.outerHTML=achievementsPanel(g);requestAnimationFrame(updatePageScrollbar)}}}
function focusAchievements(uid){const g=data.games.find(g=>g.uid===uid);if(!g)return;const panel=view.querySelector('[data-achievements]');if(panel){panel.scrollIntoView({behavior:'smooth',block:'start'});panel.focus({preventScroll:true})}return loadAchievements(g)}
function achievementsModal(uid){const g=data.games.find(g=>g.uid===uid),result=g&&achievementCache.get(achievementKey(g));if(!result)return;modal='achievements';$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal achievements-modal" role="dialog" aria-modal="true" aria-labelledby="achievements-title"><div class="modal-header"><div><span class="eyebrow">${esc(g.name)}</span><h2 id="achievements-title">Les succès <span class="achievement-count">${result.items.length}</span></h2></div><button class="close" data-action="close-modal" aria-label="Fermer">×</button></div><div class="achievement-toolbar"><input class="input" id="achievement-search" type="search" placeholder="Rechercher un succès…" aria-label="Rechercher un succès"><select class="input" id="achievement-sort" aria-label="Trier les succès"><option value="unlocked" selected>Déverrouillés en premier</option><option value="steam">Ordre Steam</option><option value="rare">Les plus rares</option><option value="name">Nom A → Z</option></select></div><div id="achievement-results" class="achievement-grid">${achievementCards(result,unlockedFirst(result.items))}</div><p class="achievement-note">Les pourcentages concernent tous les joueurs Steam. ${esc(result.progress_message||'Recherche de la progression Achievement Watcher…')}</p></section></div>`;const update=()=>{const q=$('#achievement-search').value.toLocaleLowerCase(),sort=$('#achievement-sort').value;let items=result.items.filter(a=>(a.name+' '+a.description).toLocaleLowerCase().includes(q));if(sort==='unlocked')items=unlockedFirst(items);if(sort==='rare')items.sort((a,b)=>(a.global_percent??101)-(b.global_percent??101));if(sort==='name')items.sort((a,b)=>a.name.localeCompare(b.name,'fr'));$('#achievement-results').innerHTML=items.length?achievementCards(result,items):'<p class="achievement-empty" role="status">Aucun succès ne correspond à cette recherche.</p>'};$('#achievement-search').addEventListener('input',update);$('#achievement-sort').addEventListener('change',update)}
async function refreshAchievementProgress(g){const key=achievementKey(g),result=achievementCache.get(key);if(preview||!result||achievementProgressPending.has(key))return;achievementProgressPending.add(key);try{const p=await call('GameAchievementProgress',g.uid);result.progress_message=p?.message||'Progression locale indisponible.';for(const a of result.items){const u=p?.items?.[a.id];a.known=u?.known===true;a.unlocked=u?.unlocked===true;a.unlock_time=u?.time||0;a.override=u?.override||'auto'}if(page==='detail'&&selected===g.uid){const panel=view.querySelector('[data-achievements]');if(panel?.dataset.achievements===key)panel.outerHTML=achievementsPanel(g);if(modal==='achievements'){const search=$('#achievement-search');if(search)search.dispatchEvent(new Event('input'));const note=$('#modal-root').querySelector('.achievement-note');if(note)note.textContent='Les pourcentages concernent tous les joueurs Steam. '+result.progress_message}}}catch{result.progress_message='Lecture Achievement Watcher indisponible. Nouvelle tentative automatique.'}finally{achievementProgressPending.delete(key)}}
function achievementOptions(uid){const g=data.games.find(g=>g.uid===uid),result=g&&achievementCache.get(achievementKey(g));if(!result)return;modal='achievement-options';$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal achievement-options-modal" role="dialog" aria-modal="true" aria-labelledby="achievement-options-title"><div class="modal-header"><div><span class="eyebrow">${esc(g.name)}</span><h2 id="achievement-options-title">Options des succès</h2></div><button class="close" data-action="close-modal" aria-label="Fermer">×</button></div><p class="achievement-note">Corrige un succès mal détecté. Tes choix sont enregistrés dans Ludemis et synchronisés avec Google Drive lorsque tu es connecté. « Automatique » rend la priorité à la détection.</p><input class="input" id="achievement-options-search" placeholder="Rechercher un succès…" aria-label="Rechercher un succès à corriger"><div class="achievement-options-list">${unlockedFirst(result.items).map(a=>`<label class="achievement-option-row" data-option-name="${esc(a.name.toLocaleLowerCase())}"><span>${esc(a.name)}</span><select class="input" data-achievement-option="${esc(a.id)}" aria-label="État de ${esc(a.name)}">${[['auto','Automatique'],['unlocked','Déverrouillé'],['locked','Verrouillé']].map(([value,label])=>`<option value="${value}" ${(a.override||'auto')===value?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}</div><p class="achievement-note" id="achievement-options-status" role="status">Les fichiers du jeu et d’Achievement Watcher restent inchangés.</p></section></div>`;$('#achievement-options-search').addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase();for(const row of document.querySelectorAll('[data-option-name]'))row.hidden=!row.dataset.optionName.includes(q)});for(const select of document.querySelectorAll('[data-achievement-option]'))select.addEventListener('change',async()=>{const a=result.items.find(a=>a.id===select.dataset.achievementOption),previous=a.override||'auto';select.disabled=true;try{await call('SetGameAchievementOverride',uid,a.id,select.value);a.override=select.value;await refreshAchievementProgress(g);if(modal==='achievement-options')$('#achievement-options-status').textContent='Choix enregistré sur ce PC. La synchronisation Google Drive suit tes réglages Cloud.'}catch(e){select.value=previous;if(modal==='achievement-options')$('#achievement-options-status').textContent=String(e?.message||e)}finally{select.disabled=false}})}
