const scrollTrack=$('#page-scrollbar'),scrollThumb=$('#page-scroll-thumb');
function updatePageScrollbar(){const trackHeight=scrollTrack.clientHeight,contentHeight=view.scrollHeight,viewportHeight=view.clientHeight,maxScroll=Math.max(0,contentHeight-viewportHeight);if(trackHeight<=0)return;const thumbHeight=Math.min(trackHeight-4,Math.max(45,(trackHeight-4)*viewportHeight/Math.max(contentHeight,1)));const travel=Math.max(0,trackHeight-4-thumbHeight);scrollThumb.style.height=`${thumbHeight}px`;scrollThumb.style.top=`${2+(maxScroll?view.scrollTop/maxScroll*travel:0)}px`;scrollTrack.dataset.scrollable=maxScroll>1?'true':'false';scrollTrack.setAttribute('aria-valuenow',String(maxScroll?Math.round(view.scrollTop/maxScroll*100):0));scrollTrack.setAttribute('aria-valuetext',maxScroll?`${Math.round(view.scrollTop/maxScroll*100)} %`:'Tout est visible')}
let scrollDragOffset=null;
function moveScrollbar(clientY){const rect=scrollTrack.getBoundingClientRect(),travel=scrollTrack.clientHeight-4-scrollThumb.offsetHeight,maxScroll=Math.max(0,view.scrollHeight-view.clientHeight);if(travel>0&&maxScroll>0)view.scrollTop=Math.max(0,Math.min(1,(clientY-rect.top-2-scrollDragOffset)/travel))*maxScroll;updatePageScrollbar()}
scrollTrack.addEventListener('pointerdown',e=>{if(scrollTrack.dataset.scrollable!=='true')return;e.preventDefault();scrollDragOffset=e.target===scrollThumb?e.clientY-scrollThumb.getBoundingClientRect().top:scrollThumb.offsetHeight/2;scrollTrack.setPointerCapture?.(e.pointerId);moveScrollbar(e.clientY)});
scrollTrack.addEventListener('pointermove',e=>{if(scrollDragOffset!==null)moveScrollbar(e.clientY)});
for(const type of ['pointerup','pointercancel'])scrollTrack.addEventListener(type,()=>{scrollDragOffset=null});
scrollTrack.addEventListener('keydown',e=>{const step=e.key==='ArrowDown'?60:e.key==='ArrowUp'?-60:e.key==='PageDown'?view.clientHeight*.8:e.key==='PageUp'?-view.clientHeight*.8:null;if(step!==null){e.preventDefault();view.scrollTop+=step}else if(e.key==='Home'||e.key==='End'){e.preventDefault();view.scrollTop=e.key==='Home'?0:view.scrollHeight}updatePageScrollbar()});
let detailScrollFrame=0;function updateDetailScroll(){if(!view.classList.contains('detail-view'))return;const y=Math.max(0,view.scrollTop),reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches,mast=view.querySelector('.detail-mast');const height=mast?.offsetHeight||360,progress=Math.min(1,y/(height*.9)),fade=progress*progress*(3-2*progress);view.style.setProperty('--detail-transition-opacity',String(fade));view.style.setProperty('--detail-ambient-opacity',String(.64*fade));view.style.setProperty('--detail-logo-shift',reduce?'0px':`${-Math.min(56,y*.2)}px`)}
view.addEventListener('scroll',()=>{updatePageScrollbar();if(detailScrollFrame)return;detailScrollFrame=requestAnimationFrame(()=>{detailScrollFrame=0;updateDetailScroll()})});view.addEventListener('load',event=>{if(event.target.matches?.('.detail-mast .stage-art'))updateDetailTransition(event.target);requestAnimationFrame(()=>{updatePageScrollbar();updateDetailScroll()})},true);window.addEventListener('resize',()=>{updatePageScrollbar();updateDetailScroll()});
